\subsection{Protocol M1: Optical Cavity Coherence}

\textbf{Objective:} Measure coherence time enhancement from $\xi R|\Psi|^2$ coupling

\textbf{Apparatus:}

\begin{enumerate}
\item High-finesse Fabry-Pérot cavity: $F > 10^5$, length $L = 1$ m
\item Ti:sapphire laser: $\lambda = 780$ nm, linewidth $< 1$ kHz
\item PDH locking: cavity stabilized to laser frequency
\item Photodetector: quantum efficiency $> 95\%$
\item Data acquisition: 14-bit ADC, 1 MS/s sampling
\end{enumerate}

\textbf{Procedure:}

\begin{enumerate}
\item Initialize cavity in vacuum state: wait $10\tau_{\text{thermal}}$ after pump-down
\item Inject single-photon Fock state: $|1\rangle$ via attenuated pulsed laser
\item Monitor cavity output intensity: $I(t) = |\langle\hat{a}(t)\rangle|^2$
\item Fit decay: $I(t) = I_0 e^{-t/\tau_{\text{coh}}}$
\item Extract coherence rate: $\gamma = 1/\tau_{\text{coh}}$
\end{enumerate}
